import { Component, OnInit } from '@angular/core';
import { LoadingController, ModalController, IonicPage, NavController } from 'ionic-angular';
// import { Filter } from "../../models/filter";
import { FilterCalendario } from "./filter";
import { Calendario } from "../../models/calendario";
import { CalendarioProvider } from "../../providers/calendario/calendario";
import { ImpostazioneProvider } from "../../providers/impostazione/impostazione";
import { TipologiasvuotamentoProvider } from "../../providers/tipologiasvuotamento/tipologiasvuotamento";

@IonicPage()
@Component({
  selector: 'page-calendario',
  templateUrl: 'calendario.html'
})
export class CalendarioPage implements OnInit {

  calendari: Calendario[] = [];
  elapsedTime: number;

  zona_id: number;

  filter:number;

  svuotamenti : any;
  //svuotamenti: array();

  // filter: Filter = {
  //   mag: {
  //     lower: -1,
  //     upper: 10
  //   },
  //   distance: {
  //     lower: 0,
  //     upper: 20000
  //   },
  //   time: -1,
  //   sort: 'time',
  //   myLocation: null
  // };

  constructor(private readonly calendarioProvider: CalendarioProvider,
              private readonly impostazioneProvider: ImpostazioneProvider,
              private readonly modalCtrl: ModalController,
              private readonly loadingCtrl: LoadingController,
              private readonly tipologieSvuotamentoProvider: TipologiasvuotamentoProvider,
              public navCtrl: NavController) {
  }

  ngOnInit() {
    this.tipologieSvuotamentoProvider.initProvider().then(() => this.tipologieSvuotamentoProvider.filter()
        .then((svuotamenti) => {
            // for (let el in svuotamenti){
            //     let row = svuotamenti[el];
            //     this.svuotamenti = [row["id"],row["titolo"]]
            // }
            this.svuotamenti = svuotamenti;
            this.impostazioneProvider.initProvider().then(() => this.impostazioneProvider.filter()
                .then((settings) => {
                        var count = 0;
                        for (let el in settings) {
                            let row = settings[el];
                            count++;
                            this.zona_id = row["zona_id"]
                            break;
                        }
                        if(!count){
                            this.navCtrl.setRoot('ImpostazioniPage', {}, { animate: true, direction: 'forward' });
                        }else{
                            //console.log("zona_id",zona_id)
                            this.calendarioProvider.initProvider()
                            .then(() => this.filterCalendario())
                            .catch(err => console.log(err));
                        }
                    }
                )
            )
        })
    )   
  }

  openItem(item: Calendario) {
    this.navCtrl.push('CalendarioDetailPage', { item: item });
  }

  doRefresh(refresher) {
    this.calendarioProvider.initProvider()
      .then(() => this.filterCalendario(true))
      .then(() => refresher.complete());
  }

  async filterCalendario(hideLoading = false) {
   
    let loading = null;

    if (!hideLoading) {
      loading = this.loadingCtrl.create({
        content: 'Please wait...'
      });
      loading.present();
    }

    const start = performance.now();
    this.calendari = await this.calendarioProvider.filter(this.zona_id,this.svuotamenti);
    this.elapsedTime = performance.now() - start;

    if (loading) {
      loading.dismiss();
    }
  }

  identify(index, item) {
    return item.id;
  }

  presentFilterPage() {
    const filterPage = this.modalCtrl.create(FilterCalendario, {filter: this.filter});
    filterPage.present();

    filterPage.onDidDismiss(filter => {
      if (filter) {
        this.filter = filter;
        this.filterCalendario();
      }
    });
  }

}



